19	package org.apache.pinot.common.audit;
20	
21	import java.io.IOException;
22	import javax.inject.Inject;
23	import javax.inject.Provider;
24	import javax.inject.Singleton;
25	import javax.ws.rs.container.ContainerRequestContext;
26	import javax.ws.rs.container.ContainerRequestFilter;
27	import org.glassfish.grizzly.http.server.Request;
28	
29	
30	/**
31	 * Jersey filter for audit logging of API requests.
32	 * Supports dynamic configuration through injected AuditConfigManager.
33	 */
34	@javax.ws.rs.ext.Provider
35	@Singleton
36	public class AuditLogFilter implements ContainerRequestFilter {
37	
38	  private final Provider<Request> _requestProvider;
39	  private final AuditRequestProcessor _auditRequestProcessor;
40	
41	  @Inject
42	  public AuditLogFilter(Provider<Request> requestProvider, AuditRequestProcessor auditRequestProcessor) {
43	    _requestProvider = requestProvider;
44	    _auditRequestProcessor = auditRequestProcessor;
45	  }
46	
47	  @Override
48	  public void filter(ContainerRequestContext requestContext)
49	      throws IOException {
50	    // Skip audit logging if it's not enabled to avoid unnecessary processing
51	    if (!_auditRequestProcessor.isEnabled()) {
52	      return;
53	    }
54	
55	    // Extract the remote address and delegate to the auditor
56	    final Request grizzlyRequest = _requestProvider.get();
57	    final String remoteAddr = grizzlyRequest.getRemoteAddr();
58	
59	    final AuditEvent auditEvent = _auditRequestProcessor.processRequest(requestContext, remoteAddr);
60	    if (auditEvent != null) {
61	      AuditLogger.auditLog(auditEvent);
62	    }
63	  }
64	}
