19	package org.apache.pinot.common.audit;
20	
21	import com.fasterxml.jackson.databind.ObjectMapper;
22	import org.slf4j.Logger;
23	import org.slf4j.LoggerFactory;
24	
25	
26	/**
27	 * Utility class for audit logging in Pinot components.
28	 * Uses SLF4J with structured JSON logging format and supports dynamic configuration.
29	 */
30	public final class AuditLogger {
31	
32	  private static final String PINOT_AUDIT_LOGGER_NAME = "org.apache.pinot.audit";
33	  static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();
34	  // Default Pinot logger. For logging failures in audit logging itself
35	  private static final Logger LOG = LoggerFactory.getLogger(AuditLogger.class);
36	  private static final Logger AUDIT_LOGGER = LoggerFactory.getLogger(PINOT_AUDIT_LOGGER_NAME);
37	
38	  private AuditLogger() {
39	    // Private constructor to prevent instantiation
40	  }
41	
42	  /**
43	   * Logs an audit event as structured JSON at INFO level.
44	   * Implements graceful degradation - audit logging failures will not propagate
45	   * and will be logged separately for monitoring.
46	   *
47	   * @param auditEvent the audit event to log
48	   */
49	  public static void auditLog(AuditEvent auditEvent) {
50	    if (auditEvent == null) {
51	      return;
52	    }
53	
54	    try {
55	      // Log the JSON to a single line (follow ndjson standard)
56	      String jsonLog = OBJECT_MAPPER.writeValueAsString(auditEvent);
57	      AUDIT_LOGGER.info(jsonLog);
58	    } catch (Exception e) {
59	      // Graceful degradation: Never let audit logging failures affect the main request
60	      LOG.error("Failed to write audit log entry for endpoint: {} method: {}", auditEvent.getEndpoint(),
61	          auditEvent.getMethod(), e);
62	    }
63	  }
64	}
