35	/**
36	 * Configuration manager for audit logging settings.
37	 * Handles dynamic configuration updates from cluster configuration changes.
38	 * Note. Needs to be registered with the provided cluster config provider to listen to config changes
39	 */
40	@Singleton
41	public final class AuditConfigManager implements PinotClusterConfigChangeListener {
42	  private static final Logger LOG = LoggerFactory.getLogger(AuditConfigManager.class);
43	  private static final String AUDIT_CONFIG_PREFIX = "pinot.audit";
44	  private static final Map<ServiceRole, String> SERVICE_ROLE_CONFIG_PREFIX_MAP =
45	      Map.of(ServiceRole.CONTROLLER, "controller", ServiceRole.SERVER, "server", ServiceRole.BROKER, "broker");
46	
47	  private final String _configPrefix;
48	  private AuditConfig _currentConfig = new AuditConfig();
49	
50	  @Inject
51	  public AuditConfigManager(ServiceRole serviceRole) {
52	    _configPrefix = constructAuditConfigPrefix(serviceRole);
53	  }
54	
55	  /**
56	   * Maps cluster configuration properties with a common prefix to a POJO using Jackson.
57	   * Uses PinotConfiguration.subset() to extract properties with the given prefix and
58	   * Jackson's convertValue() for automatic object mapping.
59	   */
60	  @VisibleForTesting
61	  static AuditConfig buildFromClusterConfig(Map<String, String> clusterConfigs, String auditConfigPrefix) {
62	    final MapConfiguration mapConfig = new MapConfiguration(clusterConfigs);
63	    final PinotConfiguration subsetConfig = new PinotConfiguration(mapConfig).subset(auditConfigPrefix);
64	    return AuditLogger.OBJECT_MAPPER.convertValue(subsetConfig.toMap(), AuditConfig.class);
65	  }
66	
67	  private static String constructAuditConfigPrefix(ServiceRole serviceRole) {
68	    String componentPrefix = SERVICE_ROLE_CONFIG_PREFIX_MAP.get(serviceRole);
69	    Objects.requireNonNull(componentPrefix, "Unsupported service role: " + serviceRole);
70	    return AUDIT_CONFIG_PREFIX + "." + componentPrefix;
71	  }
72	
73	  public AuditConfig getCurrentConfig() {
74	    return _currentConfig;
75	  }
76	
77	  public boolean isEnabled() {
78	    return _currentConfig.isEnabled();
79	  }
80	
81	  @Override
82	  public void onChange(Set<String> changedConfigs, Map<String, String> clusterConfigs) {
83	    boolean hasAuditConfigChanges = changedConfigs.stream().anyMatch(key -> key.startsWith(_configPrefix));
84	
85	    if (!hasAuditConfigChanges) {
86	      LOG.info("No audit-related configs changed, skipping configuration rebuild");
87	      return;
88	    }
89	
90	    try {
91	      _currentConfig = buildFromClusterConfig(clusterConfigs, _configPrefix);
92	      LOG.info("Successfully updated audit configuration");
93	    } catch (Exception e) {
94	      LOG.error("Failed to update audit configuration from cluster configs", e);
95	    }
96	  }
97	}
