68	  /**
69	   * Converts a MultivaluedMap into a Map of query parameters.
70	   * If a key in the MultivaluedMap has a single value, that value is added directly to the resulting map.
71	   * If a key has multiple values, the list of values is added instead.
72	   *
73	   * @param multimap the input MultivaluedMap containing keys and their associated values
74	   * @param allowedKeys optional set of allowed keys for case-insensitive filtering.
75	   *                    If null or empty, all keys are included
76	   * @return a Map where each key is mapped to either a single value or a list of values
77	   */
78	  private static Map<String, Object> toMap(MultivaluedMap<String, String> multimap, Set<String> allowedKeys) {
79	    Map<String, Object> resultMap = new HashMap<>();
80	    boolean filterKeys = allowedKeys != null && !allowedKeys.isEmpty();
81	
82	    for (Map.Entry<String, List<String>> entry : multimap.entrySet()) {
83	      String key = entry.getKey();
84	      // Skip if filtering is enabled and key is not in allowed list (case-insensitive)
85	      if (filterKeys && !allowedKeys.contains(key.toLowerCase())) {
86	        continue;
87	      }
88	
89	      List<String> values = entry.getValue();
90	      if (values.size() == 1) {
91	        resultMap.put(key, values.get(0));
92	      } else {
93	        resultMap.put(key, values);
94	      }
95	    }
96	    return resultMap;
97	  }
