package org.apache.pinot.common.audit;

import java.io.IOException;
import java.util.UUID;
import javax.inject.Inject;
import javax.inject.Provider;
import javax.inject.Singleton;
import javax.ws.rs.container.ContainerRequestContext;
import javax.ws.rs.container.ContainerRequestFilter;
import javax.ws.rs.container.ContainerResponseContext;
import javax.ws.rs.container.ContainerResponseFilter;
import org.glassfish.grizzly.http.server.Request;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;


/**
 * Jersey filter for audit logging of API requests and responses.
 * Supports dynamic configuration through injected AuditConfigManager.
 * When response auditing is enabled, a unique request identifier is generated during request
 * filtering and reused during response filtering so that request and response audit events
 * can be correlated.
 */
@javax.ws.rs.ext.Provider
@Singleton
public class AuditLogFilter implements ContainerRequestFilter, ContainerResponseFilter {

  private static final Logger LOG = LoggerFactory.getLogger(AuditLogFilter.class);

  /**
   * Property key used to store the {@link AuditResponseContext} in the {@link ContainerRequestContext}
   * so it can be retrieved during response filtering.
   */
  static final String AUDIT_RESPONSE_CONTEXT_PROPERTY = "audit.response.context";

  private static final long NANOS_PER_MILLI = 1_000_000L;

  private final Provider<Request> _requestProvider;
  private final AuditRequestProcessor _auditRequestProcessor;
  private final AuditConfigManager _auditConfigManager;

  @Inject
  public AuditLogFilter(Provider<Request> requestProvider, AuditRequestProcessor auditRequestProcessor,
      AuditConfigManager auditConfigManager) {
    _requestProvider = requestProvider;
    _auditRequestProcessor = auditRequestProcessor;
    _auditConfigManager = auditConfigManager;
  }

  @Override
  public void filter(ContainerRequestContext requestContext)
      throws IOException {
    // Set up the response correlation context before anything else so that a response can be audited
    // even if request processing produces no audit event.
    setupResponseContext(requestContext);

    // Skip audit logging if it's not enabled to avoid unnecessary processing
    if (!_auditRequestProcessor.isEnabled()) {
      return;
    }

    // Extract the remote address and delegate to the auditor
    final Request grizzlyRequest = _requestProvider.get();
    final String remoteAddr = grizzlyRequest.getRemoteAddr();

    final AuditEvent auditEvent = _auditRequestProcessor.processRequest(requestContext, remoteAddr);
    if (auditEvent != null) {
      AuditLogger.auditLog(auditEvent);
    }
  }

  @Override
  public void filter(ContainerRequestContext requestContext, ContainerResponseContext responseContext) {
    try {
      final AuditConfig config = _auditConfigManager.getCurrentConfig();
      // Only audit responses when both the global audit system and response capture are enabled
      if (config == null || !config.isEnabled() || !config.isCaptureResponseEnabled()) {
        return;
      }

      final Object contextProperty = requestContext.getProperty(AUDIT_RESPONSE_CONTEXT_PROPERTY);
      if (!(contextProperty instanceof AuditResponseContext)) {
        return;
      }

      final AuditResponseContext responseAuditContext = (AuditResponseContext) contextProperty;
      final String requestId = responseAuditContext.getRequestId();
      final long startTimeNanos = responseAuditContext.getStartTimeNanos();
      if (requestId == null || startTimeNanos <= 0) {
        return;
      }

      final long durationMs = (System.nanoTime() - startTimeNanos) / NANOS_PER_MILLI;

      final AuditEvent auditEvent = new AuditEvent().setRequestId(requestId)
          .setResponseCode(responseContext.getStatus())
          .setDurationMs(durationMs)
          .setEndpoint(requestContext.getUriInfo().getPath())
          .setMethod(requestContext.getMethod());
      AuditLogger.auditLog(auditEvent);
    } catch (Exception e) {
      // Graceful degradation: Never let audit logging failures affect the HTTP response
      LOG.warn("Failed to process audit logging for response", e);
    }
  }

  /**
   * Creates and stores an {@link AuditResponseContext} when response auditing is enabled, so the
   * response filter can correlate the response with the request via a shared identifier.
   */
  private void setupResponseContext(ContainerRequestContext requestContext) {
    try {
      final AuditConfig config = _auditConfigManager.getCurrentConfig();
      if (config == null || !config.isEnabled() || !config.isCaptureResponseEnabled()) {
        return;
      }

      final AuditResponseContext responseContext = new AuditResponseContext().setRequestId(UUID.randomUUID().toString())
          .setStartTimeNanos(System.nanoTime());
      requestContext.setProperty(AUDIT_RESPONSE_CONTEXT_PROPERTY, responseContext);
    } catch (Exception e) {
      // Graceful degradation: Never let audit logging failures affect the request
      LOG.warn("Failed to set up audit response context", e);
    }
  }
}
